#include <stdlib.h>
#include <string.h>
#include <omp.h>

#define MR 6
#define NR 16
#define KC 256
#define MC 72
#define NCG 256   /* columns per work item (multiple of NR) */

typedef float v8 __attribute__((vector_size(32)));

static inline v8 ldu(const float *p) { v8 v; memcpy(&v, p, sizeof(v)); return v; }
static inline void stu(float *p, v8 v) { memcpy(p, &v, sizeof(v)); }

static void kernel(int kc, const float *restrict a, const float *restrict b,
                   float *restrict c, int ldc, int mr, int nr, int accum)
{
    v8 c00 = {0}, c01 = {0}, c10 = {0}, c11 = {0}, c20 = {0}, c21 = {0};
    v8 c30 = {0}, c31 = {0}, c40 = {0}, c41 = {0}, c50 = {0}, c51 = {0};

    for (int k = 0; k < kc; k++) {
        v8 b0 = *(const v8 *)(b + 16 * k);
        v8 b1 = *(const v8 *)(b + 16 * k + 8);
        const float *ap = a + 6 * k;
        float a0 = ap[0], a1 = ap[1], a2 = ap[2], a3 = ap[3], a4 = ap[4], a5 = ap[5];
        c00 += a0 * b0; c01 += a0 * b1;
        c10 += a1 * b0; c11 += a1 * b1;
        c20 += a2 * b0; c21 += a2 * b1;
        c30 += a3 * b0; c31 += a3 * b1;
        c40 += a4 * b0; c41 += a4 * b1;
        c50 += a5 * b0; c51 += a5 * b1;
    }

    v8 acc[6][2] = {{c00, c01}, {c10, c11}, {c20, c21},
                    {c30, c31}, {c40, c41}, {c50, c51}};

    if (mr == MR && nr == NR) {
        for (int i = 0; i < MR; i++) {
            float *cp = c + (size_t)i * ldc;
            if (accum) {
                stu(cp, ldu(cp) + acc[i][0]);
                stu(cp + 8, ldu(cp + 8) + acc[i][1]);
            } else {
                stu(cp, acc[i][0]);
                stu(cp + 8, acc[i][1]);
            }
        }
    } else {
        float tmp[MR][NR] __attribute__((aligned(64)));
        for (int i = 0; i < MR; i++) {
            stu(&tmp[i][0], acc[i][0]);
            stu(&tmp[i][8], acc[i][1]);
        }
        for (int i = 0; i < mr; i++) {
            float *cp = c + (size_t)i * ldc;
            if (accum)
                for (int j = 0; j < nr; j++) cp[j] += tmp[i][j];
            else
                for (int j = 0; j < nr; j++) cp[j] = tmp[i][j];
        }
    }
}

static void *alloc64(size_t bytes)
{
    bytes = (bytes + 63) & ~(size_t)63;
    if (bytes == 0) bytes = 64;
    return aligned_alloc(64, bytes);
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;

    int npanels = (n + NR - 1) / NR;
    float *Bp = (float *)alloc64((size_t)npanels * NR * KC * sizeof(float));
    int nib = (n + MC - 1) / MC;
    int njb = (n + NCG - 1) / NCG;
    int nitems = nib * njb;

    #pragma omp parallel
    {
        float *Ap = (float *)alloc64((size_t)((MC + MR - 1) / MR) * MR * KC * sizeof(float));

        for (int pc = 0; pc < n; pc += KC) {
            int kc = n - pc < KC ? n - pc : KC;
            int accum = pc > 0;

            /* pack B[pc:pc+kc, :] into NR-wide panels */
            #pragma omp for schedule(static)
            for (int jp = 0; jp < npanels; jp++) {
                float *dst = Bp + (size_t)jp * kc * NR;
                int j0 = jp * NR;
                int nr = n - j0 < NR ? n - j0 : NR;
                for (int k = 0; k < kc; k++) {
                    const float *src = B + (size_t)(pc + k) * n + j0;
                    float *d = dst + k * NR;
                    int j = 0;
                    for (; j < nr; j++) d[j] = src[j];
                    for (; j < NR; j++) d[j] = 0.0f;
                }
            }

            #pragma omp for schedule(dynamic, 1)
            for (int it = 0; it < nitems; it++) {
                int ib = it / njb, jb = it % njb;
                int ic = ib * MC;
                int mc = n - ic < MC ? n - ic : MC;
                int jc = jb * NCG;
                int nc = n - jc < NCG ? n - jc : NCG;

                /* pack A[ic:ic+mc, pc:pc+kc] into MR-row panels */
                for (int ir = 0; ir < mc; ir += MR) {
                    float *dst = Ap + (size_t)(ir / MR) * kc * MR;
                    int mr = mc - ir < MR ? mc - ir : MR;
                    for (int ii = 0; ii < MR; ii++) {
                        if (ii < mr) {
                            const float *src = A + (size_t)(ic + ir + ii) * n + pc;
                            for (int k = 0; k < kc; k++) dst[k * MR + ii] = src[k];
                        } else {
                            for (int k = 0; k < kc; k++) dst[k * MR + ii] = 0.0f;
                        }
                    }
                }

                for (int jr = 0; jr < nc; jr += NR) {
                    int j = jc + jr;
                    int nr = n - j < NR ? n - j : NR;
                    const float *bp = Bp + (size_t)(j / NR) * kc * NR;
                    for (int ir = 0; ir < mc; ir += MR) {
                        int mr = mc - ir < MR ? mc - ir : MR;
                        kernel(kc, Ap + (size_t)(ir / MR) * kc * MR, bp,
                               C + (size_t)(ic + ir) * n + j, n, mr, nr, accum);
                    }
                }
            }
        }
        free(Ap);
    }
    free(Bp);
}
```
Observation: Compiled and passed the correctness checks.
Runtime: 7.5 ms.
Speedup versus the naive triple loop: 278.42x.
Feedback: **Feedback on Attempt 0 (7.5 ms, about 270 GFLOP/s at n≈1000)**

1. **ISA width.** The 6×16 kernel uses 12 ymm accumulators, which suits AVX2/FMA. If the host has AVX-512, the kernel uses only half the vector width. Add an `#ifdef __AVX512F__` path with 512-bit vectors, for example a 12×32 or 14×32 micro-kernel using 24–28 zmm accumulators. Keep 6×16 as the fallback.

2. **Redundant A packing.** Each (ib, jb) work item repacks the same A block, so A is packed `njb` (4) times per `pc`. Pack A once per `pc` into a shared buffer, in parallel, then split the compute.

3. **Barriers and C passes.** With KC=256 you get about 4 `pc` iterations. Each one has two implicit barriers plus a full read-modify-write of C. Raise KC to 384–512, which still fits L2 for an MC panel. This halves the barriers and the C traffic.

4. **Work decomposition.** 56 dynamic items of 72×256 each give poor balance at high thread counts, and each item touches cold B panels. Try a 2D static partition where each thread owns a contiguous column slab of C. That keeps its B panels L2-resident across all `ic`.

5. **Minor.**
   - Add `__builtin_prefetch` for the next A/B micro-panels and for the C tile before the store.
   - Unroll the k-loop by 4.
   - Hoist the `aligned_alloc` calls out of the parallel region.
   - Consider adding `-ffast-math`.

