               __builtin_prefetch(c + (size_t)(i) * ldc + NR - 1, 1, 3);
#define STFULL(i) { float *cp = c + (size_t)(i) * ldc; \
    if (accum) { stu(cp, ldu(cp) + c##i##_0); stu(cp + VW, ldu(cp + VW) + c##i##_1); } \
    else { stu(cp, c##i##_0); stu(cp + VW, c##i##_1); } }
#define STTMP(i) stu(&tmp[i][0], c##i##_0); stu(&tmp[i][VW], c##i##_1);

static inline void kernel(int kc, const float *restrict a, const float *restrict b,
                          float *restrict c, int ldc, int mr, int nr, int accum)
{
    ROWS(DECL)
    if (mr == MR) { ROWS(PFC) }

    #pragma GCC unroll 4
    for (int k = 0; k < kc; k++) {
        vf b0 = *(const vf *)(b + NR * k);
        vf b1 = *(const vf *)(b + NR * k + VW);
        const float *ap = a + MR * k;
        ROWS(STEP)
    }

    if (mr == MR && nr == NR) {
        ROWS(STFULL)
    } else {
        float tmp[MR][NR] __attribute__((aligned(64)));
        ROWS(STTMP)
        for (int i = 0; i < mr; i++) {
            float *cp = c + (size_t)i * ldc;
            if (accum)
                for (int j = 0; j < nr; j++) cp[j] += tmp[i][j];
            else
                for (int j = 0; j < nr; j++) cp[j] = tmp[i][j];
