            #pragma omp for schedule(static) nowait
            for (int it = 0; it < nitems; it++) {
                int jb = it / nib, ib = it % nib;
                int ic = ib * MC;
                int mc = n - ic < MC ? n - ic : MC;
                int jc = jb * NCG;
                int nc = n - jc < NCG ? n - jc : NCG;

