        float tmp[MR][NR] __attribute__((aligned(64)));
        for (int i = 0; i < MR; i++) {
            stu(&tmp[i][0], acc[i][0]);
            stu(&tmp[i][8], acc[i][1]);
        }
        for (int i = 0; i < mr; i++) {
