                        int mr = n - i < MR ? n - i : MR;
                        const float *ap = Ap + (size_t)ip * kc * MR;
                        float *cc = C + (size_t)i * n + j;
                        if (pc > 0) kernel(kc, ap, bp, cc, n, mr, nr, 1);
                        else        kernel(kc, ap, bp, cc, n, mr, nr, 0);
                    }
                }
            }
        }
    }
}
